// In case focus escapes the trap for some strange reason, pull it back in.
const isNodeAttached = function (node) {
  // Check if node is still connected to the DOM (standard API) or fallback to ownerDocument containment
  return node?.isConnected ?? (node?.ownerDocument?.documentElement?.contains?.(node) ?? false);
};

const checkFocusIn = function (e) {
  const target = getActualTarget(e);
  const targetContained = findContainerIndex(target, e) >= 0;

  // In Firefox when you Tab out of an iframe the Document is briefly focused.
  if (targetContained || target instanceof Document) {
    if (targetContained) {
      state.mostRecentlyFocusedNode = target;
    }
  } else {
    // escaped! pull it back in to where it just left
    e.stopImmediatePropagation();
    let focusNode = state.mostRecentlyFocusedNode;
    // If the most recently focused node is no longer attached or not focusable, use the initial focus node.
    if (
      !focusNode ||
      !isNodeAttached(focusNode) ||
      !isFocusable(focusNode, config.tabbableOptions)
    ) {
      focusNode = getInitialFocusNode();
    }
    tryFocus(focusNode);
  }
};
